(7252793, 1127060, 8759, '<td valign="top">the tilted horizon bothers me a lot. nice find otherwise</td>', 'the tilted horizon bothers me a lot. nice find otherwise', '2014-08-19 05:40:30.000000', NULL, 1),
(7252794, 1126909, 8759, '<td valign="top">i would have preferred the focus on the end with blurry foregorund</td>', 'i would have preferred the focus on the end with blurry foregorund', '2014-08-19 05:41:45.000000', NULL, 1),
(7252795, 1127126, 8759, '<td valign="top">somehow this image took me <a href="//en.wikipedia.org/wiki/The_Elephant_Vanishes" rel="nofollow" target="_blank">here</a></td>', 'somehow this image took me here', '2014-08-19 05:46:13.000000', NULL, 1),
